import icontract


@icontract.require(lambda n: n >= 0)
@icontract.require(lambda n: n >= 2)
@icontract.ensure(lambda n, result: (not result) or all(n % k != 0 for k in range(2, n)))
@icontract.ensure(lambda n, result: result or any(n % k == 0 for k in range(2, n)))
def isPrime(n: int) -> bool:
